def backfill_sellers(apps, schema_editor):
    """
    Mavjud sotuvchilarni yangi oqimga o'tkazadi.

    Sotuvchi paneli endi  ga qarab ochiladi. Bu maydonsiz
    allaqachon mahsulot sotayotgan foydalanuvchilar panelidan ayrilib
    qolardi — shuning uchun rol SELLER/ADMIN bo'lganlarga (yoki mahsuloti
    borlarga) sanani o'rnatamiz.
    """
    User = apps.get_model("core", "User")
    now = timezone.now()
    qs = User.objects.filter(seller_since__isnull=True).filter(
        models.Q(role__in=["SELLER", "ADMIN"]) | models.Q(products__isnull=False)
    ).distinct()
    for user in qs:
        user.seller_since = user.created_at or now
        user.save(update_fields=["seller_since"])


def noop(apps, schema_editor):
    pass


